using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Qks.Shared;
using QksExcelAddIn.Modeling.Core;
using QksExcelAddIn.ViewModels;

internal static partial class Program
{
    private static ModelSnapshot DraftFixture() => JsonCodec.Deserialize<ModelSnapshot>(JsonCodec.Read(System.IO.Path.Combine(ViewerTestRoot,"tests/fixtures/viewer-readonly.json")));
    private static DraftLoad Wall(DraftWorkspace w, double a=0, double b=3, DraftAction action=DraftAction.Add, string id=null) => DraftLoad.WallFromMetres(w.Snapshot.Elements.Single(e=>e.Id=="Frame:B1"),"SDL",10,a,b,8,12,action,id);
    private static DraftLoad Slab(string id=null) => new DraftLoad(id??Guid.NewGuid().ToString("N"),"Area:S1",DraftKind.SlabUniform,"LL",10,0,1,3,3,DraftAction.Add);
    private static void DraftTests()
    {
        Check("draft: line segment uses true 3D metres", () => {
            var frame = Frame(new Vec3(0,0,0),new Vec3(3,0,4));
            var s = new ModelSnapshot(1,"ETABS","","id","",DateTime.UtcNow,new[]{frame},Array.Empty<ModelLevel>(),Array.Empty<ExistingLoad>(),Array.Empty<string>(),new[]{"SDL"});
            var w = new DraftWorkspace(s); var d = DraftLoad.WallFromMetres(frame,"SDL",10,1,4,0,-2,DraftAction.Add); w.Put(d); Near(d.Start,.2); Near(d.End,.8); Assert(d.Value1==0 && d.Value2==-2);
        });
        Check("draft: Add keeps existing and adds separate contribution", () => {var w=new DraftWorkspace(DraftFixture()); w.Put(Wall(w)); var r=w.Compare().Where(r=>r.Phase=="Sau"&&r.Load.ElementId=="Frame:B1").ToArray(); Assert(r.Length==2&&r.Any(r=>r.Origin=="Giữ từ snapshot"));});
        Check("draft: Replace removes only matching force scope", () => {
            var f=DraftFixture(); var other=new ExistingLoad("Frame:B1","SDL","Frame moment/length","Global",10,0,1,10,10,"kN·m/m");
            var s=new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,f.Elements,f.Levels,f.Loads.Concat(new[]{other}),f.Diagnostics,f.LoadPatterns);
            var w=new DraftWorkspace(s); w.Put(Wall(w,0,3,DraftAction.ReplaceMatching)); var r=w.Compare().Where(r=>r.Phase=="Sau"&&r.Load.ElementId=="Frame:B1").ToArray(); Assert(r.Length==2&&r.Any(r=>r.Load.Kind=="Frame moment/length"));
        });
        Check("draft: adjacent segments accepted without duplicate assignments",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Wall(w,0,3,DraftAction.ReplaceMatching));w.Put(Wall(w,3,6,DraftAction.ReplaceMatching));Assert(w.Loads.Count==2&&w.Compare().Count(r=>r.Phase=="Sau"&&r.Load.ElementId=="Frame:B1")==2);});
        Check("draft: overlapping segments rejected atomically",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Wall(w));Throws<ArgumentException>(()=>w.Put(Wall(w,2,5)));Assert(w.Loads.Count==1);});
        Check("draft: conflicting add/replace scope rejected",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Wall(w));Throws<ArgumentException>(()=>w.Put(Wall(w,3,6,DraftAction.ReplaceMatching)));});
        Check("draft: duplicate slab assignment rejected",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Slab());Throws<ArgumentException>(()=>w.Put(Slab()));});
        Check("draft: update same ID replaces row and Undo restores",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w);w.Put(d);w.Put(Wall(w,1,4,DraftAction.Add,d.Id));Assert(w.Loads.Count==1);Near(w.Loads[0].Start,1.0/6);w.Undo();Near(w.Loads[0].Start,0);});
        Check("draft: editing a row preserves table order and row identity",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w);var slab=Slab();w.Put(d);w.Put(slab);w.Put(Wall(w,1,4,DraftAction.Add,d.Id));Assert(w.Loads[0].Id==d.Id&&w.Loads[1].Id==slab.Id);w.Undo();Assert(w.Loads[0].Id==d.Id&&w.Loads[1].Id==slab.Id);});
        Check("draft: Remove Undo Redo restores exact values",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w);w.Put(d);w.Remove(d.Id);Assert(w.Loads.Count==0);w.Undo();Assert(w.Loads.Single().Id==d.Id);w.Redo();Assert(w.Loads.Count==0);});
        Check("draft: edit after Undo clears Redo",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Wall(w));w.Undo();Assert(w.CanRedo);w.Put(Wall(w,3,6));Assert(!w.CanRedo);});
        Check("draft: dirty state tracks saved content across history",()=>{var w=new DraftWorkspace(DraftFixture());Assert(!w.IsDirty);w.Put(Wall(w));Assert(w.IsDirty);w.MarkSaved();Assert(!w.IsDirty);w.Undo();Assert(w.IsDirty);w.Redo();Assert(!w.IsDirty);});
        Check("draft: history retains at most 100 states",()=>{var w=new DraftWorkspace(DraftFixture());string id=Guid.NewGuid().ToString("N");for(int i=0;i<110;i++)w.Put(new DraftLoad(id,"Frame:B1",DraftKind.WallLine,"SDL",10,0,1,i,i,DraftAction.Add));int n=0;while(w.CanUndo){w.Undo();n++;}Assert(n==100);});
        Check("draft: wrong snapshot identity import rejected",()=>{var w=new DraftWorkspace(DraftFixture());var d=w.Document();Throws<ArgumentException>(()=>w.Import(new DraftDocument(1,"another",d.SnapshotFingerprint,new[]{Wall(w)})));Assert(!w.Loads.Any());});
        Check("draft: wrong baseline fingerprint import rejected",()=>{var w=new DraftWorkspace(DraftFixture());Throws<ArgumentException>(()=>w.Import(new DraftDocument(1,w.Snapshot.Identity,new string('a',64),new[]{Wall(w)})));});
        Check("draft: future draft schema rejected",()=>{var w=new DraftWorkspace(DraftFixture());Throws<ArgumentException>(()=>w.Import(new DraftDocument(2,w.Snapshot.Identity,w.Fingerprint,new[]{Wall(w)})));});
        Check("draft: duplicate IDs on import rejected atomically",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w);Throws<ArgumentException>(()=>w.Import(new DraftDocument(1,w.Snapshot.Identity,w.Fingerprint,new[]{d,d})));Assert(!w.Loads.Any());});
        Check("draft: JSON retains fingerprint actions signs and zero",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w,0,3,DraftAction.ReplaceMatching);w.Put(new DraftLoad(d.Id,d.ElementId,d.Kind,d.Pattern,d.Direction,d.Start,d.End,0,-2,d.Action));w.Put(Slab());var doc=JsonCodec.Deserialize<DraftDocument>(JsonCodec.Serialize(w.Document()));var copy=new DraftWorkspace(DraftFixture());copy.Import(doc);Assert(!copy.IsDirty&&copy.Loads.Count==2&&copy.Loads[0].Action==DraftAction.ReplaceMatching&&copy.Loads[0].Value1==0&&copy.Loads[0].Value2==-2);});
        Check("draft: packaged sample validates against offline source fixture",()=>{var w=new DraftWorkspace(DraftFixture());w.Import(JsonCodec.Deserialize<DraftDocument>(JsonCodec.Read(System.IO.Path.Combine(ViewerTestRoot,"tests/fixtures/viewer-draft.qksdraft.json"))));var after=w.Compare().Where(r=>r.Phase=="Sau").ToArray();var line=after.Single(r=>r.Load.ElementId=="Frame:B1").Load;Near(line.Start,1.0/6);Near(line.End,5.0/6);Assert(line.Value1==8&&line.Value2==10&&after.Single(r=>r.Load.ElementId=="Area:S1").Load.Value1==4);});
        Check("draft: missing JSON value cannot silently become zero",()=>{var w=new DraftWorkspace(DraftFixture());w.Put(Wall(w));var token=JObject.Parse(JsonCodec.Serialize(w.Document()));((JObject)token["Loads"][0]).Remove("Value1");Throws<JsonSerializationException>(()=>JsonCodec.Deserialize<DraftDocument>(token.ToString()));});
        Check("draft: unused host patterns remain available and survive JSON",()=>{var f=DraftFixture();var s=new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,f.Elements,f.Levels,f.Loads,f.Diagnostics,f.LoadPatterns.Concat(new[]{"UNUSED"}));var copy=JsonCodec.Deserialize<ModelSnapshot>(JsonCodec.Serialize(s));Assert(copy.LoadPatterns.Contains("UNUSED"));var w=new DraftWorkspace(copy);w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Area:S1",DraftKind.SlabUniform,"UNUSED",10,0,1,0,0,DraftAction.Add));Assert(w.Loads.Single().Value1==0);});
        Check("draft: replacing Global scope is insensitive to CSys casing",()=>{var f=DraftFixture();var loads=f.Loads.Select(l=>new ExistingLoad(l.ElementId,l.Pattern,l.Kind,"GLOBAL",l.Direction,l.Start,l.End,l.Value1,l.Value2,l.Unit));var w=new DraftWorkspace(new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,f.Elements,f.Levels,loads,f.Diagnostics,f.LoadPatterns));w.Put(Wall(w,0,3,DraftAction.ReplaceMatching));Assert(w.Compare().Count(r=>r.Phase=="Sau"&&r.Load.ElementId=="Frame:B1")==1);});
        Check("draft: fingerprint ignores capture time and API list order",()=>{var f=DraftFixture();var copy=new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,DateTime.UtcNow,f.Elements.Reverse(),f.Levels.Reverse(),f.Loads.Reverse(),f.Diagnostics,f.LoadPatterns.Reverse());Assert(SnapshotFingerprint.Of(f)==SnapshotFingerprint.Of(copy));});
        Check("draft: fingerprint detects baseline load change",()=>{var f=DraftFixture();var copy=new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,f.Elements,f.Levels,f.Loads.Skip(1),f.Diagnostics,f.LoadPatterns);Assert(SnapshotFingerprint.Of(f)!=SnapshotFingerprint.Of(copy));});
        Check("draft: same IDs with changed geometry cannot import old draft",()=>{var f=DraftFixture();var elements=f.Elements.Select(e=>e.Id=="Frame:B1"?new ModelElement(e.Id,e.Name,e.Label,e.Story,e.Property,e.Kind,new[]{e.Vertices[0],new Vec3(7,0,3)}):e);var changed=new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,elements,f.Levels,f.Loads,f.Diagnostics,f.LoadPatterns);var w=new DraftWorkspace(f);w.Put(Wall(w));Throws<ArgumentException>(()=>new DraftWorkspace(changed).Import(w.Document()));});
        Check("draft: unknown pattern rejected",()=>{var w=new DraftWorkspace(DraftFixture());Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Frame:B1",DraftKind.WallLine,"MISSING",10,0,1,1,1,DraftAction.Add)));});
        Check("draft: local/projected directions deferred",()=>{var w=new DraftWorkspace(DraftFixture());foreach(int dir in new[]{1,7,11})Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Frame:B1",DraftKind.WallLine,"SDL",dir,0,1,1,1,DraftAction.Add)));});
        Check("draft: range reversal zero length and overrun rejected",()=>{var w=new DraftWorkspace(DraftFixture());foreach(var range in new[]{new[]{-1.0,2},new[]{3.0,3},new[]{4.0,2},new[]{0.0,7}})Throws<ArgumentException>(()=>w.Put(Wall(w,range[0],range[1])));});
        Check("draft: nonfinite values rejected",()=>{var w=new DraftWorkspace(DraftFixture());foreach(double v in new[]{double.NaN,double.PositiveInfinity})Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Frame:B1",DraftKind.WallLine,"SDL",10,0,1,v,v,DraftAction.Add)));});
        Check("draft: column cannot receive wall editor draft",()=>{var w=new DraftWorkspace(DraftFixture());Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Frame:C1",DraftKind.WallLine,"SDL",10,0,1,1,1,DraftAction.Add)));});
        Check("draft: opening cannot receive slab draft",()=>{var f=DraftFixture();var hole=new ModelElement("Area:hole","hole","","","",ElementKind.Opening,f.Elements.Last().Vertices);var w=new DraftWorkspace(new ModelSnapshot(1,f.Source,f.Version,f.Identity,f.SourceUnits,f.CapturedUtc,f.Elements.Concat(new[]{hole}),f.Levels,f.Loads,f.Diagnostics,f.LoadPatterns));Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),hole.Id,DraftKind.SlabUniform,"LL",10,0,1,1,1,DraftAction.Add)));});
        Check("draft: slab must be uniform and cover original area",()=>{var w=new DraftWorkspace(DraftFixture());Throws<ArgumentException>(()=>w.Put(new DraftLoad(Guid.NewGuid().ToString("N"),"Area:S1",DraftKind.SlabUniform,"LL",10,.2,1,3,4,DraftAction.Add)));});
        Check("draft: preview never mutates snapshot",()=>{var f=DraftFixture();string before=JsonCodec.Serialize(f);var w=new DraftWorkspace(f);w.Put(Wall(w,0,3,DraftAction.ReplaceMatching));w.Compare();Assert(JsonCodec.Serialize(f)==before);});
        Check("draft: overlay clips actual draft segment in both views",()=>{var w=new DraftWorkspace(DraftFixture());var d=Wall(w,1,4);var e=w.Snapshot.Elements.Single(e=>e.Id==d.ElementId);var p=DraftOverlay.Build(d,e,ViewPlane.Plan(3,.1));var v=DraftOverlay.Build(d,e,ViewPlane.Elevation(0,0,0,.1,true));Near(p.Geometry.Segments[0].A.X,1);Near(p.Geometry.Segments[0].B.X,4);Near(v.Geometry.Segments[0].A.X,-1);Assert(p.ElementId==v.ElementId);});
        Check("draft: editor uses decimal comma and preserves draft through view switch",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftStartMetres="1,5";vm.DraftEndMetres="4,5";vm.DraftValue1="-2,5";vm.SaveEditorToDraft();vm.Elevation=true;vm.Reverse=true;Assert(vm.DraftRows.Count==1&&vm.DraftRows[0].Value2==-2.5&&vm.DraftOverlays.Count==1);Near(vm.DraftRows[0].Start,.25);});
        Check("draft: editor updates selected draft without duplicating ID",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();vm.Elevation=true;vm.DraftValue1="3";vm.SaveEditorToDraft();Assert(vm.DraftRows.Count==1&&vm.DraftRows[0].Value1==3);});
        Check("draft: source disconnect preserves saveable detached drafts",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();string fingerprint=vm.Drafts.Fingerprint;vm.SetSnapshot(null,false);Assert(vm.DraftRows.Count==1&&!vm.DraftContextActive&&!vm.CanEditDraft&&vm.DraftOverlays.Count==0&&vm.Drafts.Document().SnapshotFingerprint==fingerprint);});
        Check("draft: changed snapshot detaches old drafts instead of silently deleting",()=>{var vm=new VisualWorkspaceViewModel();var f=DraftFixture();vm.SetSnapshot(f,true);vm.SelectedElement=f.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();var other=new ModelSnapshot(1,f.Source,f.Version,"another-model",f.SourceUnits,f.CapturedUtc,f.Elements,f.Levels,f.Loads,f.Diagnostics,f.LoadPatterns);vm.SetSnapshot(other,true);Assert(vm.DraftRows.Count==1&&!vm.DraftContextActive&&!vm.CanEditDraft);Throws<InvalidOperationException>(()=>vm.SaveEditorToDraft());});
        Check("draft: refresh identical baseline reattaches drafts",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();vm.SetSnapshot(null,false);vm.SetSnapshot(DraftFixture(),true);Assert(vm.DraftContextActive&&vm.DraftRows.Count==1);});
        Check("draft: invalid import preserves existing unsaved workspace",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();var old=vm.Drafts;Throws<ArgumentException>(()=>vm.ImportDraft(new DraftDocument(1,"wrong","bad",Array.Empty<DraftLoad>())));Assert(ReferenceEquals(vm.Drafts,old)&&vm.Drafts.IsDirty);});
        Check("elevation: two point plane uses chosen axis and keeps up",()=>{var p=ViewPlane.ElevationThrough(new Vec2(2,3),new Vec2(5,7),.1);var q=p.Project(new Vec3(5,7,9));Near(q.X,5);Near(q.Y,9);Near(p.Depth(new Vec3(5,7,9)),0);});
        Check("elevation: repeated/nonfinite points rejected",()=>{Throws<ArgumentException>(()=>ViewPlane.ElevationThrough(new Vec2(1,1),new Vec2(1,1),.1));Throws<ArgumentException>(()=>ViewPlane.ElevationThrough(new Vec2(0,0),new Vec2(double.NaN,0),.1));});
        Check("elevation: invalid depth cannot begin Plan picking on a stale scene",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.Elevation=true;vm.HalfDepth="bad";Throws<ArgumentException>(()=>vm.PreparePlanPointPicking());Assert(vm.Elevation);vm.HalfDepth="0.15";vm.PreparePlanPointPicking();Assert(!vm.Elevation);});
        Check("elevation: view model two point selection retains draft source ID",()=>{var vm=new VisualWorkspaceViewModel();vm.SetSnapshot(DraftFixture(),true);vm.SelectedElement=vm.Snapshot.Elements.Single(e=>e.Id=="Frame:B1");vm.DraftPattern="SDL";vm.DraftValue1="2";vm.SaveEditorToDraft();vm.SetElevationThrough(new Vec2(0,0),new Vec2(6,0));Assert(vm.Elevation&&vm.DraftRows.Single().ElementId=="Frame:B1"&&vm.DraftOverlays.Count==1);});
    }
}
